    except ValueError as e:
        raise DashboardBadRequest(
            "step must be an integer",
            fields={"step": "invalid"},
        ) from e
    if n < 0:
        raise DashboardBadRequest(
            "step must be non-negative",
            fields={"step": "invalid"},
        )
    return n

